const m = [[1,2,3],[4,5,6],[7,8,9]];
const rotated = [];
for (let j = 0; j < 3; j++) {
  rotated[j] = [];
  for (let i = 2; i >= 0; i--) {
    rotated[j].push(m[i][j]);
  }
}
console.log(rotated);
